4	/// Discovery list + manual address entry. Manual entry is a first-class flow,
5	/// not a fallback (upstream issue #269).
6	struct ConnectionScreen: View {
7	    let session: RobotSession
8	
9	    @State private var browser: RobotBrowser
10	    @State private var manualInput: String
11	    @Environment(\.reachyPreviewMode) private var previewMode
12	    @State private var resolving: String?
13	    @State private var resolvedServiceIDs: Set<String> = []
14	    @State private var pendingCandidates: [RobotAddress] = []
15	    @State private var attemptedCandidates: Set<RobotAddress> = []
16	    @State private var autoConnectTask: Task<Void, Never>?
17	    @State private var rescanTask: Task<Void, Never>?
18	    @State private var showsOnboarding = false
19	    @State private var awaitedHardwareID = KnownRobots.pendingProvisionedHardwareID
20	
21	    /// Upstream's `INTERVALS.DISCOVERY_SCAN`.
22	    private let rescanInterval: Duration = .seconds(10)
23	
24	    init(session: RobotSession, browser: RobotBrowser = RobotBrowser(), manualInput: String? = nil) {
25	        self.session = session
26	        _browser = State(initialValue: browser)
27	        _manualInput = State(initialValue: manualInput ?? KnownRobots.lastAddress.map(\.displayString) ?? "")
28	    }
29	
30	    var body: some View {
31	        Group {
32	            if case let .connecting(.needsDaemonUpdate(_, requirement)) = session.phase {
33	                // Its own screen rather than a stepper row: retrying is pointless
34	                // here, and everything the user can do is an update decision.
35	                NavigationStack {
36	                    DaemonUpdateScreen(session: session, requirement: requirement)
37	                }
38	            } else if needsDecision {
39	                // Start / continue / cancel: the discovery list underneath would
40	                // only compete with a choice the user has to make.
41	                Form {
42	                    ConnectionStepper(session: session)
43	                }
44	                .formStyle(.grouped)
45	            } else {
46	                Form {
47	                    if isProbing {
48	                        ConnectionStepper(session: session)
49	                    }
50	                    // Disabled section by section rather than on the whole form:
51	                    // `disabled` is cumulative and a child cannot re-enable itself, which
52	                    // would take the Bluetooth setup button down with everything else —
53	                    // and the sweep it is waiting on runs every 10 s forever when nothing
54	                    // answers, which is exactly when that button is the way out.
55	                    discoverySection
56	                        .disabled(isProbing)
57	                    setUpSection
58	                    manualSection
59	                        .disabled(isProbing)
60	                    if let error = session.lastError {
61	                        Section {
62	                            Text(error)
63	                                .font(.caption.monospaced())
64	                                .foregroundStyle(.red)
65	                        }
66	                    }
67	                }
68	                .formStyle(.grouped)
69	            }
70	        }
71	        .onAppear {
72	            guard !previewMode else { return }
73	            browser.start()
74	            enqueueInitialCandidates()
75	            startPeriodicRescan()
76	            // Only the very first launch, and never as a gate: a robot already on the
77	            // network is found without any of this, and the button below reopens it.
78	            if KnownRobots.lastAddress == nil, !KnownRobots.hasCompletedOnboarding {
79	                showsOnboarding = true
80	            }
81	        }
82	        .sheet(isPresented: $showsOnboarding) {
83	            OnboardingFlow(onFinish: finishOnboarding) { showsOnboarding = false }
84	        }
85	        .onChange(of: browser.services) { _, services in
86	            resolveDiscoveredServices(services)
87	        }
88	        .onDisappear {
89	            autoConnectTask?.cancel()
90	            autoConnectTask = nil
91	            rescanTask?.cancel()
92	            rescanTask = nil
93	            browser.stop()
94	        }
95	    }
