97	    /// An attempt is in flight and will resolve itself. Shown inline so the
98	    /// discovery list stays put while the candidate sweep walks its addresses.
99	    private var isProbing: Bool {
100	        switch session.phase {
101	        case .connecting(.handshaking), .connecting(.checkingBackend): true
102	        default: false
103	        }
104	    }
105	
106	    /// The attempt stopped and needs the user.
107	    private var needsDecision: Bool {
108	        switch session.phase {
109	        case .connecting(.backendUnavailable), .connecting(.failed): true
110	        default: false
111	        }
