161	    private var setUpSection: some View {
162	        Section {
163	            if let awaitedHardwareID {
164	                Label(
165	                    "Waiting for the robot you just set up (\(awaitedHardwareID)). "
166	                        + "If this phone is still on reachy-mini-ap, switch it back to your home Wi-Fi.",
