178	    /// The robot reported where it landed over Bluetooth, which beats waiting for the
179	    /// sweep to stumble across it. The hardware id is what confirms the arrival, and
180	    /// `RobotSession` clears it on the handshake.
181	    private func finishOnboarding(_ outcome: OnboardingOutcome) {
182	        showsOnboarding = false
183	        awaitedHardwareID = outcome.hardwareID
184	        guard let address = outcome.address else { return }
185	        attemptedCandidates.remove(address)
