190	        Section("Manual address") {
191	            Label(
192	                "The daemon uses unencrypted HTTP without authentication. Connect only on a trusted private network.",
193	                systemImage: "lock.open.trianglebadge.exclamationmark"
194	            )
195	            .font(.caption)
196	            .foregroundStyle(.orange)
197	            TextField("host, host:port, or IP", text: $manualInput)
198	                .autocorrectionDisabled()
199	            #if os(iOS)
200	                .keyboardType(.URL)
201	                .textInputAutocapitalization(.never)
202	            #endif
203	            Button("Connect") {
204	                guard let address = RobotAddress(parsing: manualInput) else { return }
205	                connectManually(to: address)
206	            }
207	            .disabled(RobotAddress(parsing: manualInput) == nil)
208	            if KnownRobots.lastAddress != nil {
209	                Button("Forget last robot", role: .destructive) {
210	                    KnownRobots.lastAddress = nil
211	                    manualInput = ""
212	                }
213	            }
214	        }
215	    }
