217	    /// Tries known/static candidates first; Bonjour results are appended as they resolve.
218	    private func enqueueInitialCandidates() {
219	        guard session.automaticConnectionAllowed else { return }
220	        // Upstream also probes `reachy-mini.home`, which cannot work here: App
221	        // Transport Security exempts `.local`, link-local and single-label names
222	        // from its HTTPS requirement, and a qualified `.home` name is none of
223	        // those. Probing it only ever produced a -1022 error on screen.
224	        var candidates = [RobotAddress(host: "reachy-mini.local")]
225	        #if os(macOS) || targetEnvironment(simulator)
226	            // A simulated daemon runs on this Mac and advertises no Bonjour the
227	            // simulator can see; loopback reaches the host either way.
228	            candidates.insert(RobotAddress(host: "127.0.0.1"), at: 0)
229	        #endif
230	        if let last = KnownRobots.lastAddress {
231	            candidates.insert(last, at: 0)
232	        }
233	        enqueue(candidates)
234	    }
235	
236	    /// A robot powered on after this screen appeared advertises nothing our
237	    /// browser can react to when mDNS doesn't reach us, so the known addresses
238	    /// have to be retried instead of being written off after one failed pass.
239	    private func startPeriodicRescan() {
240	        rescanTask?.cancel()
241	        rescanTask = Task { @MainActor in
242	            while !Task.isCancelled {
243	                try? await Task.sleep(for: rescanInterval)
244	                guard !Task.isCancelled, session.phase == .idle else { continue }
245	                attemptedCandidates = []
246	                enqueueInitialCandidates()
247	            }
248	        }
249	    }
250	
251	    private func resolveDiscoveredServices(_ services: [RobotBrowser.DiscoveredService]) {
252	        guard session.automaticConnectionAllowed else { return }
253	        for service in services where !resolvedServiceIDs.contains(service.id) {
254	            resolvedServiceIDs.insert(service.id)
255	            Task { @MainActor in
256	                if let address = await BonjourResolver.resolve(service.endpoint) {
257	                    enqueue([address])
258	                }
259	            }
260	        }
261	    }
262	
263	    private func enqueue(_ candidates: [RobotAddress]) {
264	        for candidate in candidates
265	            where !attemptedCandidates.contains(candidate) && !pendingCandidates.contains(candidate)
266	        {
267	            pendingCandidates.append(candidate)
268	        }
269	        startAutoConnectIfNeeded()
270	    }
271	
272	    private func startAutoConnectIfNeeded() {
273	        guard autoConnectTask == nil,
274	              session.automaticConnectionAllowed,
275	              session.phase == .idle,
276	              !pendingCandidates.isEmpty
277	        else { return }
278	
279	        autoConnectTask = Task { @MainActor in
280	            defer { autoConnectTask = nil }
281	            while !Task.isCancelled,
282	                  session.automaticConnectionAllowed,
283	                  session.phase == .idle,
284	                  !pendingCandidates.isEmpty
285	            {
286	                let candidate = pendingCandidates.removeFirst()
287	                attemptedCandidates.insert(candidate)
288	                if await session.connect(to: candidate, automatically: true) {
289	                    return
290	                }
291	            }
292	        }
293	    }
294	
295	    private func connectManually(to address: RobotAddress) {
296	        autoConnectTask?.cancel()
297	        autoConnectTask = nil
298	        Task { await session.connect(to: address) }
299	    }
300	
301	    private func connect(to service: RobotBrowser.DiscoveredService) {
302	        autoConnectTask?.cancel()
303	        autoConnectTask = nil
304	        resolving = service.id
305	        Task {
306	            defer { resolving = nil }
307	            guard let address = await BonjourResolver.resolve(service.endpoint) else { return }
308	            await session.connect(to: address)
309	        }
310	    }
311	}
