1	import Foundation
2	import Network
3	import Observation
4	
5	/// Bonjour discovery of robot daemons.
6	///
7	/// Watches both service types the daemon advertises: `_reachy-mini._tcp`
8	/// (primary) and `_http._tcp` (legacy, instance names containing "reachy").
9	/// A browser stuck in `.waiting(kDNSServiceErr_PolicyDenied)` means the user
10	/// denied Local Network permission — discovery is otherwise silently empty.
11	@MainActor
12	@Observable
13	public final class RobotBrowser {
14	    public struct DiscoveredService: Identifiable, Hashable, Sendable {
15	        public var id: String {
16	            "\(type)/\(name)"
17	        }
18	
19	        public let name: String
20	        public let type: String
21	        public let endpoint: NWEndpoint
22	    }
23	
24	    public private(set) var servicesByType: [String: [DiscoveredService]] = [:]
25	    public private(set) var browserStates: [String: String] = [:]
26	    private var browsers: [NWBrowser] = []
27	
28	    public nonisolated static let serviceTypes = ["_reachy-mini._tcp", "_http._tcp"]
29	
30	    public init() {}
31	
32	    public var services: [DiscoveredService] {
33	        servicesByType.values.flatMap(\.self).sorted { $0.id < $1.id }
34	    }
35	
36	    public var permissionLooksDenied: Bool {
37	        browserStates.values.contains(where: Self.stateLooksPolicyDenied)
38	    }
39	
40	    nonisolated static func stateLooksPolicyDenied(_ state: String) -> Bool {
41	        state.contains("PolicyDenied") || state.contains("-65570")
42	    }
43	
44	    nonisolated static func acceptsService(name: String, type: String) -> Bool {
45	        !type.hasPrefix("_http") || name.localizedCaseInsensitiveContains("reachy")
46	    }
47	
48	    public func start() {
49	        stop()
50	        for type in Self.serviceTypes {
51	            let browser = NWBrowser(for: .bonjour(type: type, domain: nil), using: .tcp)
52	            browser.stateUpdateHandler = { [weak self] state in
53	                Task { @MainActor in
54	                    self?.browserStates[type] = "\(state)"
55	                }
56	            }
57	            browser.browseResultsChangedHandler = { [weak self] results, _ in
58	                let found = results.compactMap { result -> DiscoveredService? in
59	                    guard case let .service(name, serviceType, _, _) = result.endpoint,
60	                          Self.acceptsService(name: name, type: serviceType)
61	                    else { return nil }
62	                    return DiscoveredService(name: name, type: serviceType, endpoint: result.endpoint)
63	                }
64	                Task { @MainActor in
65	                    self?.servicesByType[type] = found
66	                }
67	            }
68	            browser.start(queue: .main)
69	            browsers.append(browser)
70	        }
71	    }
72	
73	    public func stop() {
74	        browsers.forEach { $0.cancel() }
75	        browsers = []
76	        servicesByType = [:]
77	        browserStates = [:]
78	    }
79	}
