81	public enum BonjourResolver {
82	    /// Resolves a discovered Bonjour service to a concrete host:port by opening
83	    /// a throwaway TCP connection and reading the remote endpoint.
84	    public static func resolve(_ endpoint: NWEndpoint, timeout: Duration = .seconds(5)) async -> RobotAddress? {
85	        let connection = NWConnection(to: endpoint, using: .tcp)
86	        defer { connection.cancel() }
87	        return await withTaskGroup(of: RobotAddress?.self) { group in
88	            group.addTask {
89	                await withCheckedContinuation { continuation in
90	                    let resumed = Atomic(false)
91	                    connection.stateUpdateHandler = { state in
92	                        let finish: (RobotAddress?) -> Void = { address in
93	                            guard !resumed.swap(true) else { return }
94	                            continuation.resume(returning: address)
95	                        }
96	                        switch state {
97	                        case .ready:
98	                            if case let .hostPort(host, port) = connection.currentPath?.remoteEndpoint,
99	                               let host = Self.hostString(host)
100	                            {
101	                                finish(RobotAddress(host: host, port: Int(port.rawValue)))
102	                            } else {
103	                                finish(nil)
104	                            }
105	                        case .failed, .cancelled:
106	                            finish(nil)
107	                        default:
108	                            break
109	                        }
110	                    }
111	                    connection.start(queue: .global())
112	                }
113	            }
114	            group.addTask {
115	                try? await Task.sleep(for: timeout)
116	                return nil
117	            }
118	            let first = await group.next() ?? nil
119	            group.cancelAll()
120	            return first
121	        }
122	    }
123	
124	    static func hostString(_ host: NWEndpoint.Host) -> String? {
125	        switch host {
126	        case let .ipv4(address):
127	            // NWEndpoint appends an interface zone ("%lo0") that is garbage in a URL.
128	            return stripZone("\(address)")
129	        case let .ipv6(address):
130	            let value = "\(address)"
131	            // A link-local address cannot be routed without its interface zone.
132	            guard !value.lowercased().hasPrefix("fe80:") || value.contains("%") else { return nil }
133	            return value.lowercased().hasPrefix("fe80:") ? value : stripZone(value)
134	        case let .name(name, _):
135	            return name
136	        @unknown default:
137	            return nil
138	        }
139	    }
140	
141	    private static func stripZone(_ s: String) -> String {
142	        s.split(separator: "%").first.map(String.init) ?? s
143	    }
144	}
