146	/// Tiny lock-protected flag for one-shot continuation resumption.
147	private final class Atomic: @unchecked Sendable {
148	    private var value: Bool
149	    private let lock = NSLock()
150	
151	    init(_ value: Bool) {
152	        self.value = value
153	    }
154	
155	    func swap(_ newValue: Bool) -> Bool {
156	        lock.lock()
157	        defer { lock.unlock() }
158	        let old = value
159	        value = newValue
160	        return old
161	    }
162	}
