165	    public extension RobotBrowser {
166	        /// A browser with results already in hand and no `NWBrowser` running.
167	        ///
168	        /// `servicesByType` and `browserStates` are `private(set)`, so this has to live in the
169	        /// same file. Denied Local Network permission is otherwise indistinguishable from an
170	        /// empty network, which is exactly the state the connection screen has to explain.
171	        static func preview(
172	            names: [String] = ["reachy-mini-4f2a", "reachy-mini-9c81"],
173	            permissionDenied: Bool = false
174	        ) -> RobotBrowser {
175	            let browser = RobotBrowser()
176	            let type = serviceTypes[0]
177	            browser.servicesByType = [
178	                type: names.map { name in
179	                    DiscoveredService(
180	                        name: name,
181	                        type: type,
182	                        endpoint: .service(name: name, type: type, domain: "local.", interface: nil)
183	                    )
184	                },
185	            ]
186	            if permissionDenied {
187	                browser.browserStates = [type: "waiting(-65570: PolicyDenied)"]
188	            }
189	            return browser
190	        }
191	    }
192	#endif
