4	/// Entry point for the shared UI: connection flow → robot control, with one live
5	/// viewport placed according to how much room there is.
6	///
7	/// The tab bar lives here rather than in the app target because the Live tab and
8	/// the Robot tab share a `RobotSession` and a `ViewportModel`, and because
9	/// whether Live exists at all depends on the size class — which an `App` cannot
10	/// read. Diagnostics is injected so the app target keeps owning its own screen
11	/// without a second, nested tab bar.
12	public struct ReachyRootView<Diagnostics: View>: View {
13	    private enum TabID: Hashable {
14	        case robot
15	        case live
16	        case diagnostics
17	    }
18	
19	    @State private var session: RobotSession
20	    @State private var viewport: ViewportModel
21	    @State private var tab: TabID = .robot
22	    @State private var showsSettings = false
23	    @Environment(\.scenePhase) private var scenePhase
24	    @Environment(\.reachyPreviewMode) private var previewMode
25	
26	    #if os(macOS)
27	        /// `horizontalSizeClass` does not exist on macOS, where a window is always
28	        /// wide enough for the two-column layout.
29	        private var isCompact: Bool {
30	            false
31	        }
32	    #else
33	        @Environment(\.horizontalSizeClass) private var horizontalSizeClass
34	        private var isCompact: Bool {
35	            horizontalSizeClass == .compact
36	        }
37	    #endif
38	
39	    private let diagnostics: Diagnostics
40	
41	    @MainActor
42	    public init(@ViewBuilder diagnostics: () -> Diagnostics) {
43	        self.init(session: RobotSession(), diagnostics: diagnostics)
44	    }
45	
46	    /// Internal so previews can park the root in a phase a real connection would have to reach.
47	    @MainActor
48	    init(
49	        session: RobotSession,
50	        viewport: ViewportModel = ViewportModel(),
51	        @ViewBuilder diagnostics: () -> Diagnostics
52	    ) {
53	        _session = State(initialValue: session)
54	        _viewport = State(initialValue: viewport)
55	        self.diagnostics = diagnostics()
56	    }
57	
58	    public var body: some View {
59	        TabView(selection: $tab) {
60	            Tab("Robot", systemImage: "figure.wave", value: TabID.robot) {
61	                robotTab
62	            }
63	            if offersLiveTab {
64	                Tab("Live", systemImage: "cube.transparent", value: TabID.live) {
65	                    liveTab
66	                }
67	            }
68	            Tab("Diagnostics", systemImage: "stethoscope", value: TabID.diagnostics) {
69	                diagnostics
70	            }
71	        }
72	        .task(id: viewportAddress) {
73	            guard !previewMode else { return }
74	            if let viewportAddress {
75	                viewport.attach(to: viewportAddress)
