import Foundation
import Network

// Four variants side by side. Only the descriptor/parameters differ.
struct Variant {
    let label: String
    let descriptor: NWBrowser.Descriptor
    let parameters: NWParameters
}

let p2p: NWParameters = {
    let p = NWParameters()
    p.includePeerToPeer = true
    return p
}()

let variants = [
    Variant(label: "A: type+nil domain, .tcp", descriptor: .bonjour(type: "_reachy-mini._tcp", domain: nil), parameters: .tcp),
    Variant(label: "B: type+local. domain, .tcp", descriptor: .bonjour(type: "_reachy-mini._tcp", domain: "local."), parameters: .tcp),
    Variant(label: "C: type+nil domain, NWParameters()", descriptor: .bonjour(type: "_reachy-mini._tcp", domain: nil), parameters: NWParameters()),
    Variant(label: "D: type+nil domain, p2p", descriptor: .bonjour(type: "_reachy-mini._tcp", domain: nil), parameters: p2p),
]

var browsers: [NWBrowser] = []
for variant in variants {
    let browser = NWBrowser(for: variant.descriptor, using: variant.parameters)
    browser.stateUpdateHandler = { print("[\(variant.label)] state: \(state: $0)") }
    browser.browseResultsChangedHandler = { results, _ in
        print("[\(variant.label)] results: \(results.count)")
        for r in results { print("    \(r.endpoint)") }
    }
    browser.start(queue: .main)
    browsers.append(browser)
}

extension String.StringInterpolation {
    mutating func appendInterpolation(state: NWBrowser.State) { appendLiteral("\(state)") }
}

DispatchQueue.main.asyncAfter(deadline: .now() + 10) {
    print("--- done ---")
    exit(0)
}
RunLoop.main.run()

