    func discoveredCountsAsReachable() async throws {
        // The probe never answers, so only the discovery result can move this off `.checking`.
        let model = KnownRobotsModel(store: try makeStore(), interval: .seconds(60)) { _ in
            try? await Task.sleep(for: .seconds(60))
            return false
